"""Offline pause/step review for all #141 native poses, effects and captures."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'art/concepts/monsters-v1'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Depths · New monsters</title><style>
:root{color-scheme:dark;font:16px/1.5 system-ui,sans-serif;color:#e3d9c0;background:#131816}*{box-sizing:border-box}body{margin:0}main{max-width:1160px;margin:auto;padding:26px 22px 60px}h1{font:500 clamp(29px,5vw,42px)/1.15 Georgia,serif;margin:12px 0}h2{font:500 26px Georgia,serif;margin-top:28px}header small{letter-spacing:.17em;color:#b6ac83}p{color:#b8bead;max-width:80ch}a{color:#dec592}button,select{font:inherit;background:#252e25;color:inherit;border:1px solid #69715b;border-radius:3px;min-height:44px;padding:9px 13px;cursor:pointer;max-width:100%}button[aria-pressed=true],button[aria-selected=true]{background:#444932;border-color:#d9ba77}button:focus-visible,select:focus-visible{outline:2px solid #e8c986;outline-offset:3px}.controls{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:18px 0}label{display:flex;gap:8px;align-items:center;flex-wrap:wrap}[hidden]{display:none!important}.viewer{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(230px,1fr);gap:22px}.stage{min-height:350px;padding:20px;display:flex;align-items:center;justify-content:center;background:#111312;border:1px solid #434d3c}.stage[data-bg=stone]{background:#5b5a51}.stage[data-bg=paper]{background:#baaa85}.stage canvas{display:block;width:var(--pixels,384px);max-width:100%;height:auto;image-rendering:pixelated}.muted{color:#aeb6a0;font-size:14px}#meta{font-size:15px}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}.thumb{padding:8px;text-align:left;border-color:#394534}.thumb img{display:block;width:128px;height:128px;image-rendering:pixelated;margin:auto;object-fit:contain}.thumb span{display:block;font-size:14px;padding:5px 3px}.shot{display:block;width:100%;height:auto;image-rendering:pixelated;border:1px solid #46513d}.note{border-left:2px solid #9b8e63;padding-left:14px}.marks{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:10px}.mark{background:#202820;border:1px solid #3a4837;padding:12px}.mark b{display:block;font-size:14px}.marksizes{height:62px;display:flex;gap:18px;align-items:center}.marksizes img{image-rendering:pixelated}.fxgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.effect{min-width:0;padding:12px;border:1px solid #414e3b}.effect canvas{width:100%;height:auto;image-rendering:pixelated;background:#0d110f}.effect span{display:block;font-size:14px;color:#b4bca5}.effect b{font-size:15px}footer{border-top:1px solid #404b39;padding-top:18px;margin-top:30px;font-size:14px}#error{color:#ffb6a0}@media(max-width:720px){.viewer{grid-template-columns:1fr}.stage{min-height:260px}.fxgrid{grid-template-columns:1fr}.marks{grid-template-columns:repeat(2,minmax(0,1fr))}.marksizes{gap:10px}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:450px){main{padding:18px 14px 40px}.controls{gap:7px}.stage{padding:12px}.mark{padding:9px}.marksizes{gap:7px}}
</style><main><header><small>DEPTHS / MONSTER ART 141</small><h1>What came through the dark</h1><p>Eleven creatures, forty-six pose drawings. The cave bat, brute, gas-bloat and hollow miner are connected to their live definitions. The remaining creatures and special state cues are ready for Claude.</p></header>
<div class="controls" role="tablist" aria-label="Artwork"><button role="tab" id="creatures-tab" aria-controls="creatures" aria-selected="true">Creatures</button><button role="tab" id="effects-tab" aria-controls="effects" aria-selected="false">Effects &amp; marks</button></div>
<section id="creatures" role="tabpanel" aria-labelledby="creatures-tab">
<div class="controls"><label>Creature <select id="monster"></select></label><label>Pose <select id="pose"></select></label></div>
<div class="viewer"><div class="stage" id="stage" data-bg="dark"><canvas id="portrait" width="128" height="128" role="img" aria-label="Selected monster pose"></canvas></div><div>
<div class="controls"><button id="play" aria-pressed="false">Play poses</button><button id="next">Next pose</button><button id="pivot" aria-pressed="false">Show pivot</button></div>
<div class="controls"><label>Zoom <select id="zoom"><option value="1">1×</option><option value="2">2×</option><option value="3" selected>3× · fits screen</option></select></label><label>Ground <select id="background"><option value="dark">Dark</option><option value="stone">Stone</option><option value="paper">Paper</option></select></label></div>
<p id="meta"></p><p class="muted">Play cycles the authored poses for inspection; it is not a walking or attack animation loop. Paused poses stay on the same native canvas and scale. The cross marks the scene origin, not the body centre.</p>
<p><a id="master">Original pose master</a> · <a id="frames">Frame resource</a></p>
</div></div>
<h2>The full set</h2><div id="gallery" class="gallery"></div>
<h2>Inside the combat interface</h2>
<div class="controls"><label>View <select id="review"></select></label><label>Size <select id="size"><option value="phone">Phone</option><option value="desktop">Desktop</option></select></label></div>
<img id="shot" class="shot" alt="Actual Godot combat art fixture">
<p class="note">Actual BattleStage, CombatScreen and PartyCard widgets. Special poses and status marks are selected explicitly for these fixtures; existing combat code does not yet select every new state. The hanging bat changes presentation height when landed. Later combat integration must recheck action-panel clearance after this change. Phone dimensions are simulated on desktop.</p>
</section>
<section id="effects" role="tabpanel" aria-labelledby="effects-tab" hidden>
<h2>Small cues, shared vocabulary</h2><p>Native 32px marks shown at 32, 24 and 14px. Wind-up reuses the existing heavy-blow mark. These drawings do not change combat rules or apply conditions.</p><div id="marks" class="marks"></div>
<h2>Gas and failing light</h2><div class="controls"><button id="fx-play" aria-pressed="false">Play effects</button><button id="fx-step">Step frame</button><output id="fx-frame">Frame 1 / 6</output></div><div id="fxgrid" class="fxgrid"></div>
<p class="note">Four-frame gas burst and six-frame light-drained pop clear on their final frames; the lingering haze is separate. Normal alpha, restrained colour, no bright additive flash or light node. Combat/settings controllers choose when and where to show them.</p>
</section>
<p id="error" role="alert" hidden></p><footer><a href="../../../docs/new-monster-art.md">Claude handoff and rebuilding</a> · <a href="../../source/monsters-v1/generation.json">Exact built-in ImageGen prompts and hashes</a><p>Ordinary creatures: 128px. Broodmother: deliberate 192px exception. Maximum 32 shared colours per creature. Previous enemy art and all nonvisual resource fields are preserved.</p></footer></main>
<script>
const catalog=__CATALOG__,glyphs=__GLYPHS__,effects=__EFFECTS__;const $=id=>document.getElementById(id),url=p=>'../../../'+p.replace('res://',''),nice=s=>s.replaceAll('-',' ').replace(/^./,c=>c.toUpperCase());
const cache=new Map();function load(src){if(cache.has(src))return cache.get(src);const p=new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Missing: '+src));i.src=src});cache.set(src,p);return p}
let playing=false,pivot=false,effectPlaying=false,effectFrame=0,selected=catalog.assets[0],image=null,serial=0,fx=[];
function draw(){if(!image)return;const c=$('portrait'),g=c.getContext('2d');c.width=selected.canvas[0];c.height=selected.canvas[1];c.style.setProperty('--pixels',c.width*+$('zoom').value+'px');g.imageSmoothingEnabled=false;g.clearRect(0,0,c.width,c.height);g.drawImage(image,0,0);if(pivot){g.strokeStyle='#efb65e';g.lineWidth=1;g.beginPath();g.moveTo(selected.pivot[0]-6,selected.pivot[1]+.5);g.lineTo(selected.pivot[0]+6,selected.pivot[1]+.5);g.moveTo(selected.pivot[0]+.5,selected.pivot[1]-6);g.lineTo(selected.pivot[0]+.5,selected.pivot[1]+6);g.stroke()}window.monsterState={monster:selected.id,pose:$('pose').value,playing,pivot,effectFrame,effectPlaying};}
function pose(){const id=++serial;const original=selected.registration.find(r=>r.name===$('pose').value);$('master').href=url('res://'+original.source);window.poseReady=load(url(selected.poses[$('pose').value])).then(i=>{if(id!==serial)return;image=i;draw();$('meta').textContent=selected.canvas[0]+' × '+selected.canvas[1]+' px · '+Object.keys(selected.poses).length+' drawings · '+selected.visual_height_metres+' m idle height · origin '+selected.pivot.join(', ');window.currentImage=i});return window.poseReady}
function monster(){selected=catalog.assets.find(e=>e.id===$('monster').value);$('pose').replaceChildren();for(const p of Object.keys(selected.poses)){const o=new Option(nice(p),p);$('pose').add(o)}$('master').href=url('res://art/source/monsters-v1/'+selected.id+'-poses-master.png');$('frames').href=url(selected.frames);pose();for(const b of document.querySelectorAll('.thumb'))b.setAttribute('aria-pressed',String(b.dataset.id===selected.id));}
function step(){const s=$('pose');s.selectedIndex=(s.selectedIndex+1)%s.options.length;pose()}
function tab(which){$('creatures').hidden=which!=='creatures';$('effects').hidden=which!=='effects';$('creatures-tab').setAttribute('aria-selected',String(which==='creatures'));$('effects-tab').setAttribute('aria-selected',String(which==='effects'))}
function fxDraw(){for(const [c,im,e] of fx){const g=c.getContext('2d'),[w,h]=e.frame_size;g.imageSmoothingEnabled=false;g.clearRect(0,0,c.width,c.height);const f=Math.min(effectFrame,e.frame_count-1);g.drawImage(im,f*w,0,w,h,0,0,c.width,c.height)}$('fx-frame').textContent='Frame '+(effectFrame+1)+' / 6';draw()}
catalog.assets.forEach(e=>{const option=new Option(nice(e.id),e.id);$('monster').add(option);const b=document.createElement('button');b.className='thumb';b.dataset.id=e.id;b.innerHTML='<img alt="'+nice(e.id)+' idle" src="'+url(e.poses.idle)+'"><span>'+nice(e.id)+'</span>';b.onclick=()=>{$('monster').value=e.id;monster();$('monster').focus()};$('gallery').append(b)});
const views=catalog.assets.map(e=>e.id).concat(['cave-bat-swoop','cave-bat-landed','goblin-brute-wind-up','goblin-brute-recover','gas-bloat-swell','gas-bloat-burst','hollow-miner-grab','hound-pair','gas-and-status']);for(const v of views)$('review').add(new Option(nice(v),v));
function review(){$('shot').src=$('review').value+'-'+$('size').value+'.png'}
for(const [group,entries] of Object.entries(glyphs.groups))for(const [id,src] of Object.entries(entries)){const div=document.createElement('article');div.className='mark';div.innerHTML='<b>'+nice(id)+'</b><small class="muted">'+group+'</small><div class="marksizes">'+[32,24,14].map(s=>'<img alt="'+id+' '+s+'px" src="'+url(src)+'" width="'+s+'" height="'+s+'">').join('')+'</div>';$('marks').append(div)}
window.artReadyPromise=Promise.all(effects.effects.map(async e=>{const div=document.createElement('article');div.className='effect';const [w,h]=e.frame_size;div.innerHTML='<b>'+nice(e.id)+'</b><canvas width="'+w+'" height="'+h+'" role="img" aria-label="'+e.id+'"></canvas><span>'+e.frame_count+' frame'+(e.frame_count>1?'s':'')+' · '+w+' × '+h+'</span>';$('fxgrid').append(div);fx.push([div.querySelector('canvas'),await load(url(e.texture)),e])})).then(()=>{fxDraw();return Promise.all(catalog.assets.flatMap(e=>Object.values(e.poses).map(p=>load(url(p))))) }).then(()=>{window.artReady=true}).catch(e=>{$('error').hidden=false;$('error').textContent=e.message;throw e});
$('monster').onchange=monster;$('pose').onchange=pose;$('zoom').onchange=draw;$('background').onchange=()=>{$('stage').dataset.bg=$('background').value};$('review').onchange=review;$('size').onchange=review;$('creatures-tab').onclick=()=>tab('creatures');$('effects-tab').onclick=()=>tab('effects');
$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause poses':'Play poses';$('play').setAttribute('aria-pressed',String(playing));draw()};$('next').onclick=()=>{playing=false;$('play').textContent='Play poses';$('play').setAttribute('aria-pressed','false');step()};$('pivot').onclick=()=>{pivot=!pivot;$('pivot').setAttribute('aria-pressed',String(pivot));$('pivot').textContent=pivot?'Hide pivot':'Show pivot';draw()};
$('fx-play').onclick=()=>{effectPlaying=!effectPlaying;$('fx-play').textContent=effectPlaying?'Pause effects':'Play effects';$('fx-play').setAttribute('aria-pressed',String(effectPlaying));draw()};$('fx-step').onclick=()=>{effectPlaying=false;$('fx-play').textContent='Play effects';$('fx-play').setAttribute('aria-pressed','false');effectFrame=(effectFrame+1)%6;fxDraw()};
setInterval(()=>{if(playing)step()},750);setInterval(()=>{if(effectPlaying){effectFrame=(effectFrame+1)%6;fxDraw()}},125);monster();review();
</script></html>'''
html=html.replace('__CATALOG__',json.dumps(read(ROOT/'art/enemies/monsters-v1/catalog.json'))).replace('__GLYPHS__',json.dumps(read(ROOT/'art/ui/monsters-v1/catalog.json'))).replace('__EFFECTS__',json.dumps(read(ROOT/'art/effects/monsters-v1/catalog.json')))
(OUT/'inspector.html').write_text(html,encoding='utf-8',newline='\n')
print('MONSTER_INSPECTOR: all 46 poses, pause/step/pivot/background, effects/marks, actual combat captures')
